UPDATE com_code
SET GRP_NM = #{grpNm},
    DC     = #{dc},
    USE_YN = #{useYn}
WHERE GRP_CD = #{grpCd}

UPDATE com_code_dtl
SET DTL_NM   = #{dtlNm},
    DTL_ORDR = #{dtlOrdr},
    DC       = #{dc},
    USE_YN   = #{useYn}
WHERE GRP_CD = #{grpCd} AND DTL_CD = #{dtlCd}

UPDATE com_code_dtl
SET USE_YN = #{useYn}
WHERE GRP_CD = #{grpCd} AND DTL_CD = #{dtlCd}
